-- Run this ONCE on a new, empty database. It refuses to run if any categories or materials already exist,
-- so it can never wipe real data. To start over on purpose, first run:
--   delete from public.materials; delete from public.categories;
do $$ begin
  if exists (select 1 from public.categories) or exists (select 1 from public.materials) then
    raise exception 'The database already has categories or materials. Seed skipped so nothing is overwritten.';
  end if;
end $$;
